// Generate (or, with --check, verify) src/api/generated/schema.d.ts from the committed
// OpenAPI snapshot, so the frontend can never silently drift from the backend contract.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('..', import.meta.url);
const spec = new URL('../backend/openapi.json', root);
const out = new URL('src/api/generated/schema.d.ts', root);
const header =
  '// Generated by frontend/scripts/gen-api.mjs from backend/openapi.json. Do not edit.\n' +
  '// Regenerate with scripts/gen-client.sh (or .ps1) after any API contract change.\n\n';

const ast = await openapiTS(JSON.parse(await readFile(spec, 'utf8')));
const generated = header + astToString(ast).replace(/\r\n/g, '\n');

if (process.argv.includes('--check')) {
  const current = await readFile(out, 'utf8').catch(() => '');
  if (current !== generated) {
    console.error(
      `${fileURLToPath(out)} is stale. Run scripts/gen-client.sh (or .ps1) and commit the result.`,
    );
    process.exit(1);
  }
  console.log('API types are up to date.');
} else {
  await writeFile(out, generated);
  console.log(`wrote ${fileURLToPath(out)}`);
}
